func (f *finding) diagnostic() checker.Diagnostic {
	d := checker.Diagnostic{
		Pos:      f.pos,
		End:      f.pos,
		Category: f.rule,
		Message:  f.message,
		Related:  f.related,
	}
	if f.fix != nil {
		d.SuggestedFixes = []checker.SuggestedFix{*f.fix}
	}
