package main

import (
	"flag"
	"fmt"
	"io"
	"os"

	"github.com/mpyw/declscope"
)

// usageSubcommands is what the help lists besides the analyzer. main.go
// dispatches each of them before the driver sees the arguments, so the
// driver's own help cannot know of them.
const usageSubcommands = `Subcommands:

   declscope baseline [flags] [packages]
   declscope inspect  [flags] <package>
   declscope survey   [flags] [packages]
   declscope shrink   [flags] [packages]

   declscope skill install   [flags] [skill...]
   declscope skill uninstall [flags] [skill...]
   declscope skill list      [flags] [skill...]

Run a subcommand with -h for its flags.
`

// usageInstall makes the help the driver prints list the subcommands.
//
// singlechecker.Main assigns flag.Usage itself, so assigning it here would be
// undone. The flag set calls CommandLine.Usage, whose default only calls
// flag.Usage, and the driver leaves it alone: replacing it is what reaches
// -h and a flag error. By then every flag is registered, so the list below
// is the driver's. The header is the driver's layout, with the subcommands
// before the flags, which run to dozens of lines.
//
// A run with no argument at all prints the same help and exits 1, as the
// driver does. The driver answers a run with flags but no package on its own,
// without the subcommands.
//
//declscope:shared // main.go installs it before the driver runs
func usageInstall() {
	bare := len(os.Args) == 1
	if bare {
		os.Args = append(os.Args, "-h")
	}
	flag.CommandLine.Usage = func() {
		// The driver splits the Doc into paragraphs and prints the first beside
		// the name. declscope's Doc is one paragraph, so it is printed whole.
		a := declscope.Analyzer
		head := fmt.Sprintf("%s: %s\n\nUsage: %s [-flag] [package]\n\n", a.Name, a.Doc, a.Name)
		_, _ = io.WriteString(flag.CommandLine.Output(), head+usageSubcommands+"\nFlags:\n")
		flag.PrintDefaults()
		if bare {
			os.Exit(1)
		}
	}
}
// Package internal implements the declscope analysis.
//
// The analysis answers two different questions about two kinds of declaration.
//
// Package-level identifiers compete in one flat namespace, so the problem
// there is namespace pollution. An unexported identifier is private to its
// file's namespace unless a directive widens it, and the naming rule asks it
// to carry that namespace somewhere in its name, so that the owning unit is
// legible at every use site. The namespace marks ownership. It never grants
// reach.
//
// Methods and struct fields are already namespaced by the type that owns them
// and cannot collide with anything, so the problem there is not pollution but
// encapsulation: Go makes every unexported member visible to the whole
// package, with no way to say otherwise. Members are exempt from the naming
// rule, and their bound is the namespace of the type, not of the file.
//
//declscope:core
package internal

import (
	"golang.org/x/tools/go/analysis"

	"github.com/mpyw/declscope/internal/baseline"
	"github.com/mpyw/declscope/internal/measure"
)

// Run performs the analysis for one package.
func Run(pass *analysis.Pass, opts Options) (any, error) {
	build(pass, opts).report(pass, opts)
	return nil, nil
}

// Collect returns every violation in the package, ignoring any configured
// baseline. It is the entry point used to regenerate a baseline.
func Collect(pass *analysis.Pass, opts Options) []baseline.Key {
	return build(pass, opts).keysForReport(pass, opts)
}

// Survey returns the measured shape of the package: its namespaces, the
// crossings between them, what became of each, and the tally behind each rule.
// It is the entry point used by declscope survey and declscope inspect.
//
// Unlike Collect it is given options with the baseline loaded — config.Resolve
// rather than config.ResolveForBaseline — because what the baseline is
// absorbing is one of the things being reported.
func Survey(pass *analysis.Pass, opts Options) measure.Package {
	return build(pass, opts).surveyed(pass, opts)
}

// build always returns a collection, empty or not. A package the filter left
// with nothing to read still has one thing to say — that the filter is why —
// and returning nil for it would drop the report along with the work.
func build(pass *analysis.Pass, opts Options) *collection {
	c := collectFiles(pass, opts)
	if len(c.files) == 0 {
		return c
	}
	c.collectTargets(pass, opts)
	c.collectRefs(pass)
	return c
}
