		return "", "", false
	}
	d := f.decl
	if d == nil && f.dir != nil {
		if reach := m.reached(f.dir); len(reach) > 0 {
			d = reach[0]
		}
	}
	if d == nil {
		return "", "", false
	}
	return d.ns.key(), d.display, true
}

