			return opts, chain, err
		}
		if err := f.Apply(&opts); err != nil {
			return opts, chain, fmt.Errorf("%s: %w", p, err)
		}
	}
	if err := opts.Compile(); err != nil {
		return opts, chain, err
	}
	return opts, chain, nil
}

